import i18n from '~/shared/i18n/i18n';

export const formatKoreanNumber = (num: number): string => {
  const units = [
    i18n.t('koreanNumberUnits.empty'),
    i18n.t('koreanNumberUnits.man'),
    i18n.t('koreanNumberUnits.eok'),
    i18n.t('koreanNumberUnits.jo'),
    i18n.t('koreanNumberUnits.kyeong'),
    i18n.t('koreanNumberUnits.hae'),
  ];
  let result = '';
  let unitIndex = 0;

  while (num > 0) {
    const part = num % 10000;
    if (part != 0) {
      result = `${part.toLocaleString()}${units[unitIndex]}${result}`;
    }
    num = Math.floor(num / 10000);
    unitIndex++;
  }

  return result;
};
